function concrete(l, w, t, waste){
  l=+l; w=+w; t=+t; waste=(waste==null?10:+waste)/100;
  if(!(l>0)||!(w>0)||!(t>0)) return {error:'长/宽/厚须为正'};
  var volume=Math.round(l*w*t*1000)/1000;
  var bags=Math.ceil(volume*(1+waste)/0.02 - 1e-6);
  return {volume:volume, bags:bags, weightKg:bags*40}; }
var EXPORTS={concrete:concrete};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ConcreteForgePure = EXPORTS; }
